import { createHash } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import process from 'node:process';
import { build } from 'esbuild';

const repository = resolve(import.meta.dirname, '..');
const publicDirectory = resolve(repository, 'public', 'agent');
const generatedPath = resolve(repository, 'src', 'generated', 'agent-assets.ts');
const bundlePath = resolve(publicDirectory, 'resolveroom.mjs');
const bootstrapPath = resolve(publicDirectory, 'bootstrap.mjs');
const manifestPath = resolve(publicDirectory, 'manifest.json');
const temporaryBundle = `${bundlePath}.new`;
const sha256 = (value) => createHash('sha256').update(value).digest('hex');

await mkdir(publicDirectory, { recursive: true });
await mkdir(dirname(generatedPath), { recursive: true });
await build({
  entryPoints: [resolve(repository, 'scripts', 'resolveroom-agent.mjs')],
  outfile: temporaryBundle,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  external: ['bufferutil', 'utf-8-validate'],
  define: { 'globalThis.__RESOLVEROOM_BUNDLED__': 'true' },
  banner: {
    js: "import { createRequire as __resolveroomCreateRequire } from 'node:module'; const require = __resolveroomCreateRequire(import.meta.url);",
  },
  legalComments: 'none',
  sourcemap: false,
});
await rename(temporaryBundle, bundlePath);

const bootstrap = await readFile(
  resolve(repository, 'scripts', 'resolveroom-bootstrap.mjs'),
  'utf8',
);
await writeFile(bootstrapPath, bootstrap);
const bundle = await readFile(bundlePath);
const forbidden = ['github.com', 'registry.npmjs.org', '@openai/codex-sdk'];
for (const value of forbidden) {
  if (bundle.includes(Buffer.from(value)))
    throw new Error(`Self-contained ResolveRoom CLI unexpectedly references ${value}.`);
}

const packageManifest = JSON.parse(await readFile(resolve(repository, 'package.json'), 'utf8'));
const loader = `(async()=>{const [url,expected,bundle]=process.argv.slice(2,5);const origin=new URL(url).origin;let response;try{response=await fetch(url,{headers:{accept:"text/javascript"},redirect:"error"})}catch{process.stdout.write(JSON.stringify({ok:false,error:"network_access_required",message:"Run the same bundled Node invocation with network access approved for the ResolveRoom origin.",required_origin:origin,pairing_consumed:false,retry_same_arguments:true})+"\\n");process.exitCode=69;return}if(!response.ok){process.stdout.write(JSON.stringify({ok:false,error:"bootstrap_http_error",status:response.status,required_origin:origin,pairing_consumed:false,retry_same_arguments:response.status>=500})+"\\n");process.exitCode=69;return}const bytes=Buffer.from(await response.arrayBuffer());const actual=Buffer.from(await crypto.subtle.digest("SHA-256",bytes)).toString("hex");if(actual!==expected){process.stdout.write(JSON.stringify({ok:false,error:"bootstrap_integrity_failed",pairing_consumed:false,retry_same_arguments:false})+"\\n");process.exitCode=70;return}process.env.RESOLVEROOM_BOOTSTRAP_URL=url;process.env.RESOLVEROOM_BUNDLE_SHA256=bundle;process.env.RESOLVEROOM_BOOTSTRAP_ARGUMENT_OFFSET="5";await import("data:text/javascript;base64,"+bytes.toString("base64"));})()`;
const assets = {
  version: packageManifest.version,
  bootstrapSha256: sha256(Buffer.from(bootstrap)),
  bundleSha256: sha256(bundle),
  loaderBase64: Buffer.from(loader).toString('base64'),
};
await writeFile(
  manifestPath,
  `${JSON.stringify(
    {
      version: assets.version,
      bootstrap: { path: '/agent/bootstrap.mjs', sha256: assets.bootstrapSha256 },
      bundle: { path: '/agent/resolveroom.mjs', sha256: assets.bundleSha256 },
    },
    null,
    2,
  )}\n`,
);
await writeFile(
  generatedPath,
  `// Generated by scripts/build-agent-bundle.mjs.\nexport const agentAssets = ${JSON.stringify(assets, null, 2)} as const;\n`,
);
process.stdout.write(
  `[agent-bundle] Built self-contained v${assets.version} CLI (${bundle.length} bytes).\n`,
);
